Here is the commit message:
power: supply: bq256xx: Fix use-after-free in
 power_supply_changed()

Using the `devm_` variant for requesting IRQ _before_ the `devm_`
variant for allocating/registering the `power_supply` handle, means that
the `power_supply` handle will be deallocated/unregistered _before_ the
interrupt handler (since `devm_` naturally deallocates in reverse
allocation order). This means that during removal, there is a race
condition where an interrupt can fire just _after_ the `power_supply`
handle has been freed, *but* just _before_ the corresponding
unregistration of the IRQ handler has run.

This will lead to the IRQ handler calling `power_supply_changed()` with
a freed `power_supply` handle. Which usually crashes the system or
otherwise silently corrupts the memory...

Note that there is a similar situation which can also happen during
`probe()`; the possibility of an interrupt firing _before_ registering
the `power_supply` handle. This would then lead to the nasty situation
of using the `power_supply` handle *uninitialized* in
`power_supply_changed()`.

Fix this racy use-after-free by making sure the IRQ is requested _after_
the registration of the `power_supply` handle.

Fixes: 32e4978bb920 ("power: supply: bq256xx: Introduce the BQ256XX charger driver")
Signed-off-by: Waqar Hameed <waqar.hameed@axis.com>
Link: https://patch.msgid.link/39da6da8cc060fa0382ca859f65071e791cb6119.1766268280.git.waqar.hameed@axis.com
Signed-off-by: Sebastian Reichel <sebastian.reichel@collabora.com>

Here is the root cause:
during removal, devm releases resources in reverse order, so the power supply is freed before the IRQ handler is unregistered. An interrupt arriving during that window calls `power_supply_changed()` with a freed `power_supply` handle, causing a use-after-free. Similarly, during probe, an interrupt could fire before the power supply is registered, leading to use of an uninitialized handle.

Here is the patch:

 static int bq256xx_probe(struct i2c_client *client)
 {
 	const struct i2c_device_id *id = i2c_client_get_device_id(client);
 	struct device *dev = &client->dev;
 	struct bq256xx_device *bq;
 	struct power_supply_config psy_cfg = { };

 	int ret;

 	bq = devm_kzalloc(dev, sizeof(*bq), GFP_KERNEL);
 	if (!bq)
 		return -ENOMEM;

 	bq->client = client;
 	bq->dev = dev;
 	bq->chip_info = i2c_get_match_data(client);

 	mutex_init(&bq->lock);

 	strscpy(bq->model_name, id->name, sizeof(bq->model_name));

 	bq->regmap = devm_regmap_init_i2c(client,
 					bq->chip_info->bq256xx_regmap_config);

 	if (IS_ERR(bq->regmap)) {
 		dev_err(dev, "Failed to allocate register map\n");
 		return PTR_ERR(bq->regmap);
 	}

 	i2c_set_clientdata(client, bq);

 	ret = bq256xx_parse_dt(bq, &psy_cfg, dev);
 	if (ret) {
 		dev_err(dev, "Failed to read device tree properties%d\n", ret);
 		return ret;
 	}

 	ret = devm_add_action_or_reset(dev, bq256xx_charger_reset, bq);
 	if (ret)
 		return ret;

 	/* OTG reporting */
 	bq->usb2_phy = devm_usb_get_phy(dev, USB_PHY_TYPE_USB2);
 	if (!IS_ERR_OR_NULL(bq->usb2_phy)) {
 		INIT_WORK(&bq->usb_work, bq256xx_usb_work);
 		bq->usb_nb.notifier_call = bq256xx_usb_notifier;
 		usb_register_notifier(bq->usb2_phy, &bq->usb_nb);
 	}

 	bq->usb3_phy = devm_usb_get_phy(dev, USB_PHY_TYPE_USB3);
 	if (!IS_ERR_OR_NULL(bq->usb3_phy)) {
 		INIT_WORK(&bq->usb_work, bq256xx_usb_work);
 		bq->usb_nb.notifier_call = bq256xx_usb_notifier;
 		usb_register_notifier(bq->usb3_phy, &bq->usb_nb);
 	}

+	ret = bq256xx_power_supply_init(bq, &psy_cfg, dev);
+	if (ret) {
+		dev_err(dev, "Failed to register power supply\n");
+		return ret;
+	}
+
 	if (client->irq) {
 		ret = devm_request_threaded_irq(dev, client->irq, NULL,
 						bq256xx_irq_handler_thread,
 						IRQF_TRIGGER_FALLING |
 						IRQF_ONESHOT,
 						dev_name(&client->dev), bq);
 		if (ret < 0) {
 			dev_err(dev, "get irq fail: %d\n", ret);
 			return ret;
 		}
 	}

-	ret = bq256xx_power_supply_init(bq, &psy_cfg, dev);
-	if (ret) {
-		dev_err(dev, "Failed to register power supply\n");
-		return ret;
-	}
-
 	ret = bq256xx_hw_init(bq);
 	if (ret) {
 		dev_err(dev, "Cannot initialize the chip.\n");
 		return ret;
 	}

 	return ret;
 }



